<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue';
import {useRoute} from 'vue-router';
import {api} from '@/lib/api';
import {useAuthStore} from '@/stores/auth';
import {useServerStore} from '@/stores/server';
import {useConfirmStore} from '@/stores/confirm';
import type {DrivingSession} from '@/lib/drivingSessions';
import ServerDetail from '@/pages/ServerDetail.vue';
import Broadcast from '@/pages/Broadcast.vue';
import TrackImage from '@/components/TrackImage.vue';
const route=useRoute(),auth=useAuthStore(),server=useServerStore(),confirm=useConfirmStore();
interface Recap {executions:{id:number;instance_id:number;state:string;requested_at:number;started_at:number|null;ended_at:number|null;failure:string;setup:DrivingSession['setup']}[];stints:{id:number;execution_id:number;connection_id:number|null;guid:string;guest_id:number|null;name:string;phase:number;car:string;track:string;layout:string;laps:number;best_lap_ms:number;drift_best:number;finish_pos:number|null}[];media:{id:number;execution_id:number;guid:string;guest_id:number|null;kind:string;url:string;caption:string;captured_at:number}[];results:{id:number;execution_id:number;name:string;created_at:number}[]}
const recap=ref<Recap|null>(null);
const phaseName=(phase:number)=>({0:'Booking',1:'Practice',2:'Qualifying',3:'Race'}[phase]??'Driving');
const lapTime=(ms:number)=>ms>0?`${Math.floor(ms/60000)}:${((ms%60000)/1000).toFixed(3).padStart(6,'0')}`:'—';
const session=ref<DrivingSession|null>(null),error=ref(''),busy=ref(false);
const watching=computed(()=>route.name==='session-watch');
async function load(){try{session.value=await api.get<DrivingSession>(`/api/driving-sessions/${route.params.sessionId}`);recap.value=await api.get<Recap>(`/api/driving-sessions/${route.params.sessionId}/recap`);error.value=''}catch(e){error.value=String(e)}}
async function finish(){if(!session.value||busy.value)return;const s=session.value;const running=['live','starting'].includes(s.lifecycle);const drivers=running?(server.instances[s.instance_id??0]?.players??0):0;if(!await confirm.ask({title:running?'Finish this session?':'Cancel this plan?',message:running?`Stop this session and disconnect ${drivers} connected drivers. Saved results and moments remain with their original owners.`:'Remove this session from the pending plan. The current drive continues.',confirmLabel:running?'Finish & see recap':'Cancel plan'}))return;busy.value=true;try{session.value=await api.post<DrivingSession>(`/api/driving-sessions/${s.id}/finish`);await server.bootstrapLiveState();await load()}catch(e){error.value=String(e)}finally{busy.value=false}}
watch(()=>server.instanceList.map(i=>`${i.id}:${i.running}`).join(','),load);watch(()=>route.params.sessionId,load);onMounted(load);
</script>
<template><div v-if="error" role="alert" class="pitlane-error">{{ error }} <button @click="load">Retry</button></div><p v-if="!session&&!error">Loading session…</p><template v-if="session"><Broadcast v-if="watching&&session.instance_id" :target-instance-id="session.instance_id" /><template v-else><header class="pitlane-heading"><div><span class="pitlane-eyebrow">{{ session.experience }} · {{ session.lifecycle }}</span><h1>{{ session.name }}</h1><p>{{ session.failure || 'The setup, the driving, and what you keep from it.' }}</p></div><div class="pitlane-actions"><RouterLink v-if="session.lifecycle==='draft'&&auth.canOperate" :to="`/sessions/${session.id}/edit`" class="pitlane-button primary">Review & start</RouterLink><RouterLink v-if="session.lifecycle==='live'" :to="`/sessions/${session.id}/watch`" class="pitlane-button primary">Watch</RouterLink><button v-if="auth.canOperate&&['live','starting','planned','queued'].includes(session.lifecycle)" class="pitlane-button" :disabled="busy" @click="finish">{{ session.lifecycle==='live'?'Finish session':'Cancel plan' }}</button><RouterLink v-if="auth.canOperate" :to="`/sessions/new?again=${session.id}`" class="pitlane-button">Run it again</RouterLink></div></header><ServerDetail v-if="session.lifecycle==='live'&&session.instance_id" :target-instance-id="session.instance_id" /><div v-else class="pitlane-grid session-recap-summary"><article class="pitlane-card"><TrackImage :track-key="session.setup.track_key" :config="session.setup.track_config" class="h-44 rounded-lg mb-5" /><h2>{{ session.setup.track_key }}</h2><p>{{ session.setup.track_config || 'Default layout' }} · {{ session.experience }}</p><p>{{ session.setup.grid.entries?.reduce((n,e)=>n+(e.count??1),0) }} grid slots</p><p v-if="session.scheduled_at">Scheduled {{ new Date(session.scheduled_at).toLocaleString() }} · {{ session.time_zone }}</p></article><article class="pitlane-card"><h2>{{ session.lifecycle==='finished'?'An evening to keep.':'Your driving plan' }}</h2><p v-if="session.started_at">Started {{ new Date(session.started_at).toLocaleString() }}</p><p v-if="session.ended_at">Ended {{ new Date(session.ended_at).toLocaleString() }}</p><p v-if="session.instance_id">Server: {{ server.instances[session.instance_id]?.name || session.instance_id }}</p><RouterLink v-if="session.instance_id" :to="`/queue?instance=${session.instance_id}`" class="pitlane-button">Running order & repeat</RouterLink></article></div><section v-if="recap" class="pitlane-section"><h2 class="text-2xl mb-5">The drives behind this session</h2><p v-if="!recap.executions.length" class="text-muted">No execution has been requested yet.</p><article v-for="execution in recap.executions" :key="execution.id" class="pitlane-card mb-5"><div class="flex flex-wrap justify-between gap-4"><h3>Drive {{ execution.id }} · {{ execution.state }}</h3><span>{{ new Date(execution.started_at??execution.requested_at).toLocaleString() }}</span></div><p v-if="execution.failure" class="pitlane-error mt-4">{{ execution.failure }}</p><p>Server {{ server.instances[execution.instance_id]?.name||execution.instance_id }} · {{ execution.setup.track_key }} / {{ execution.setup.track_config||'default' }}</p><details class="mt-4"><summary>Saved setup for this drive</summary><pre class="text-xs overflow-auto max-h-72 mt-4">{{ JSON.stringify(execution.setup,null,2) }}</pre></details></article><h2 class="text-2xl mb-5 mt-9">Drivers & results</h2><p v-if="!recap.stints.length" class="text-muted">No completed driver phases have been recorded for these executions.</p><div v-else class="overflow-x-auto"><table class="w-full text-sm"><thead><tr class="text-left border-b border-line"><th class="p-3">Driver</th><th>Phase</th><th>Car</th><th>Laps</th><th>Best lap</th><th>Drift best</th><th>Finish</th></tr></thead><tbody><tr v-for="stint in recap.stints" :key="stint.id" class="border-b border-line"><td class="p-3"><RouterLink :to="stint.guest_id?`/guest-drivers/${stint.guest_id}`:`/drivers/${encodeURIComponent(stint.guid)}`">{{ stint.name }}</RouterLink><small class="block text-muted">Drive {{ stint.execution_id }}</small></td><td>{{ phaseName(stint.phase) }}</td><td>{{ stint.car }}</td><td>{{ stint.laps }}</td><td>{{ lapTime(stint.best_lap_ms) }}</td><td>{{ stint.drift_best.toLocaleString() }}</td><td>{{ stint.finish_pos||'—' }}</td></tr></tbody></table></div><div class="pitlane-actions mt-5"><a v-for="result in recap.results" :key="result.id" :href="`/api/driving-sessions/${session.id}/results/${result.id}`" target="_blank" rel="noopener" class="pitlane-button">Result file · drive {{ result.execution_id }}</a><RouterLink to="/sessions/drives" class="pitlane-button">All driving stints & tags</RouterLink><RouterLink to="/history" class="pitlane-button">Legacy result files</RouterLink></div><h2 class="text-2xl mt-10 mb-5">Moments to keep</h2><p v-if="!recap.media.length" class="text-muted">No captured moments for these executions yet.</p><div class="pitlane-grid"><article v-for="moment in recap.media" :key="moment.id" class="pitlane-card"><video v-if="moment.kind==='clip'" :src="moment.url" controls preload="metadata" class="w-full aspect-video object-contain bg-black"/><img v-else :src="moment.url" :alt="moment.caption" class="w-full aspect-video object-contain" loading="lazy"/><h3 class="mt-4">{{ moment.caption }}</h3><p>Drive {{ moment.execution_id }} · {{ new Date(moment.captured_at).toLocaleString() }}</p><a :href="`${moment.url}?download=1`" class="pitlane-button mt-4">Download moment</a></article></div></section></template></template></template>

<style scoped>.session-recap-summary{grid-template-columns:repeat(2,minmax(0,1fr))}@media(max-width:767px){.session-recap-summary{grid-template-columns:1fr}}</style>
